package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPracticalCritBank3 {
    private const val T = "දෘෂ්ටිකෝණ, මානව ව්‍යුහය, ප්‍රායෝගික මාධ්‍ය හා විචාරය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("රේඛීය දෘෂ්ටිකෝණ චිත්‍රයක නරඹන්නා සිටගෙන වස්තුව දෙස බලන ස්ථානය හඳුන්වන්නේ කුමන නමින්ද?", "නිරීක්ෂක ස්ථානය (Station Point)", "අතුරුදන් ලක්ෂ්‍යය (Vanishing Point)", "ක්ෂිතිජ රේඛාව (Horizon Line)", "චිත්‍ර තලය (Picture Plane)", "නරඹන්නා සිටින ස්ථානය හා දුර අනුව වස්තූන් කෙතරම් විශාලව හෝ ඇලවී පෙනේද යන්න තීරණය වේ."),
        q("නරඹන්නා සහ දර්ශනය අතර පිහිටි නොපෙනෙන වීදුරු තිරයක් බඳු, සිතුවම අඳින කල්පිත තලය කුමක්ද?", "චිත්‍ර තලය (Picture Plane)", "භූමි රේඛාව (Ground Line)", "මධ්‍ය අක්ෂය (Central Axis)", "වර්ණ චක්‍රය (Color Wheel)", "අප දකින ත්‍රිමාණ දර්ශනය ද්විමාන කඩදාසිය මතට ප්‍රක්ෂේපණය වන කල්පිත තලය මෙයයි."),
        q("දෘෂ්ටිකෝණ චිත්‍ර සැලැස්මක චිත්‍ර තලය පොළොව සමඟ සම්බන්ධ වන පහළම සීමා රේඛාව හඳුන්වන්නේ කෙසේද?", "භූමි රේඛාව (Ground Line)", "ක්ෂිතිජ රේඛාව (Horizon Line)", "විකර්ණ රේඛාව (Diagonal Line)", "සමෝච්ඡ රේඛාව (Contour Line)", "වස්තූන්ගේ සැබෑ උස මැනීම ආරම්භ කරන පොළොව මට්ටම දැක්වීමට භූමි රේඛාව භාවිත කෙරේ."),
        q("නිරීක්ෂකයා සිටගෙන සිටින විට වඩා බිම හිඳගෙන චිත්‍රයක් අඳින විට 'ක්ෂිතිජ රේඛාව' (Eye Level) වෙනස් වන්නේ කෙසේද?", "පහළට ගමන් කරයි", "ඉහළට ගමන් කරයි", "සම්පූර්ණයෙන් අතුරුදන් වෙයි", "සිරස් අතට හැරෙයි", "ක්ෂිතිජ රේඛාව සෑම විටම නරඹන්නාගේ ඇස් මට්ටම අනුගමනය කරන බැවින් ඉරියව්ව අනුව එය උස් හෝ පහත් වේ."),
        q("ක්ෂිතිජ රේඛාවට 'පහළින්' මේසයක් මත තබා ඇති ඝනකයක (Cube) අපට පැහැදිලිව පෙනෙන මතුපිට කුමක්ද?", "ඉහළ මතුපිට (Top surface)", "පහළ අඩිය (Bottom surface)", "පසුපස බිත්තිය (Back face)", "ඇතුළත කුහරය (Hollow core)", "ඇස් මට්ටමට පහළින් ඇති ඕනෑම පෙට්ටියක හෝ භාජනයක උඩු මුහුණත හා විවරය අපට පෙනේ."),
        q("වෘත්තාකාර කටක් ඇති වීදුරුවක් හරියටම නරඹන්නාගේ 'ඇස් මට්ටමේ' (Eye Level) තැබූ විට එහි කට පෙනෙන්නේ කෙසේද?", "සෘජු තිරස් රේඛාවක් ලෙස", "පූර්ණ වෘත්තයක් ලෙස", "පළල් ඉලිප්සයක් ලෙස", "ත්‍රිකෝණයක් ලෙස", "ඇස් මට්ටමේදී වෘත්තයේ මතුපිට නොපෙනී ඉදිරිපස හා පසුපස දාර එකම සරල රේඛාවක් සේ පෙනේ."),
        q("වෘත්තාකාර බඳුනක් ඇස් මට්ටමෙන් ක්‍රමයෙන් පහළට ගෙන යන විට එහි විවරයේ 'ඉලිප්සය' (Ellipse) වෙනස් වන්නේ කෙසේද?", "ක්‍රමයෙන් වඩා පළල් වී පෙනේ", "ක්‍රමයෙන් සිහින් ඉරක් බවට පත්වේ", "හතරැස් කොටුවක් බවට හැරේ", "කිසිදු වෙනසක් සිදු නොවේ", "ඇස් මට්ටමෙන් දුරස් වන තරමට ඉලිප්සයේ සිරස් පළල වැඩි වී වෘත්තයට ආසන්න වේ."),
        q("කෙනෙකු නරඹන්නා දෙසට කෙළින්ම අත දිගු කර සිටින විට එම අත සැබෑ දිගට වඩා කෙටි වී පෙනෙන දෘෂ්ටි සංසිද්ධිය කුමක්ද?", "සංකෝචන දෘෂ්ටිය (Foreshortening)", "වායව දෘෂ්ටිකෝණය (Aerial Perspective)", "සමාන්තර ප්‍රක්ෂේපණය (Isometric View)", "කැඩපත් සමමිතිය (Mirror Symmetry)", "වස්තුවක් ඇස දෙසට කෝණයකින් යොමු වූ විට එහි දිග අඩු වී ඉදිරි කොටස විශාලව පෙනීම මෙයයි."),
        q("නිශ්චල ජීව චිත්‍රයක වස්තූන් අතර සාපේක්ෂ ප්‍රමාණය නිවැරදිව මැන ගැනීමට ශිල්පීන් භාවිත කරන සරල මිනුම් ක්‍රමය කුමක්ද?", "පැන්සල හා මාපටැඟිල්ල යොදා දිගු ඇසින් මැනීම", "කම්පාස් හා කෝදුව වස්තුව මත තබා ඇඳීම", "වස්තූන් කඩදාසිය මත තබා වටේට ඉරි ඇඳීම", "බර කිරන තරාදියකින් වස්තු මැන බැලීම", "එක් ඇසක් වසා අත කෙළින් දිගු කර පැන්සල මත මාපටැඟිල්ල තබා අනුපාත සංසන්දනය කිරීම ප්‍රායෝගික ක්‍රමයයි."),
        q("චිත්‍රයක වස්තු කිහිපයක් හෝ මිනිස් සිරුරක් ඇල නොවී කෙළින් පිහිටා ඇත්දැයි බැලීමට පැන්සල සිරස්ව අල්ලා බලන ක්‍රමය කුමක්ද?", "සිරස් පෙළගැස්ම පරීක්ෂාව (Plumb Line)", "තිරස් වර්ණ පරීක්ෂාව (Color Check)", "දිය සායම් සේදුම් පරීක්ෂාව (Wash Test)", "ත්‍රිමාණ මැටි පරීක්ෂාව (Clay Test)", "කණකට පහළින් උරහිස හෝ වළලුකර පිහිටන ආකාරය සිරස් රේඛාවක් ඇසුරෙන් මෙලෙස නිවැරදි කෙරේ."),
        q("සංකීර්ණ පුටුවක් හෝ ගසක් නිවැරදිව ඇඳීමට අපහසු විට එහි කොටස් අතර ඇති හිස් ඉඩ හැඩතල දෙස බලා ඇඳීමේ ක්‍රමය කුමක්ද?", "සෘණ අවකාශ චිත්‍රණය (Negative Space Drawing)", "පාරාන්ධ තීන්ත ආලේපනය (Opaque Painting)", "අන්ධ සමෝච්ඡ සටහන (Blind Contour)", "තිත් සෙවණැලි ක්‍රමය (Stippling)", "පුටු කකුල් අතර හිස් කොටස්වල හැඩය ඇඳීමෙන් මිනිස් මොළයේ පූර්ව නිගමන දෝෂ මගහැරේ."),
        q("රේඛීය දෘෂ්ටිකෝණය මෙන් අතුරුදන් ලක්ෂ්‍යයකට රේඛා එකතු නොවී, සමාන්තර රේඛා දිගටම සමාන්තරව අඳින තාක්ෂණික චිත්‍ර ක්‍රමය කුමක්ද?", "සමමිතික ප්‍රක්ෂේපණය (Isometric Drawing)", "ත්‍රි-ලක්ෂ්‍ය දෘෂ්ටිකෝණය (3-Point Perspective)", "පණුවාගේ ඇසේ දසුන (Worm's-eye View)", "වායුගෝලීය දෘෂ්ටිකෝණය (Aerial Perspective)", "ගෘහ නිර්මාණ හා ඉංජිනේරු සැලසුම්වලදී නිවැරදි මිනුම් පෙන්වීමට සමමිතික රේඛා යොදා ගැනේ."),
        q("නිශ්චල ජීව චිත්‍රයක මේසය මත තැබූ කළයක් අවකාශයේ පාවෙන සේ නොපෙනී මේසය මත ස්ථිරව පිහිටි බව දැක්වීමට අනිවාර්යයෙන් ඇඳිය යුත්තේ කුමක්ද?", "වස්තුව යට ඇති පතිත සෙවණැල්ල (Cast Shadow)", "මේසය වටා දීප්තිමත් රතු රාමුවක්", "අහසේ පියාඹන කුරුල්ලන් කිහිපයක්", "වස්තුව උඩින් තැබූ අතිරේක මලක්", "වස්තුව හා මේසය ස්පර්ශ වන දාරයේ ඇති තද සෙවණැල්ල වස්තුවට බරක් හා ස්ථාවරත්වයක් දෙයි."),
        q("සම්මත වැඩිහිටි මානව මුහුණක ඉදිරිපස දසුනේදී 'නාසයේ පහළ දාරය' සිට 'නිකට' දක්වා දුරෙන් ඉහළ තුනෙන් එකක පමණ පිහිටන්නේ කුමක්ද?", "මුඛය හෙවත් තොල් පෙළ", "ඇහිබැමි යුගලය", "කන් දෙකේ මුදුන", "හිසකෙස් ආරම්භක රේඛාව", "හිසකෙස් සීමාව-ඇහිබැම-නාසය-නිකට සමාන තුනෙන් කොටස්වලට බෙදා මුඛය නාසයට මඳක් ආසන්නව ස්ථානගත කෙරේ."),
        q("මිනිස් මුහුණක ඉදිරිපස සමානුපාත අනුව, සාමාන්‍යයෙන් කටේ දෙපස කෙළවරවල් සිරස්ව පිහිටන්නේ මුහුණේ කුමන අංගයට කෙළින්ද?", "ඇස් දෙකේ මධ්‍ය කළු ඉංගිරියාවට කෙළින්", "කන් දෙකේ පිටත දාරයට කෙළින්", "නාස් පුඩු දෙකේ මැදට කෙළින්", "ඇහිබැමි දෙකේ අභ්‍යන්තර කෙළවරට කෙළින්", "විවේකී ඉරියව්වේදී තොල් කෙළවර ඇසේ මධ්‍යම කළු ඉංගිරියාවේ සිරස් රේඛාව අසල පිහිටයි."),
        q("වැඩිහිටි මානව මුහුණක ඉදිරිපස පළල කම්මුල් ප්‍රදේශයේදී සාමාන්‍යයෙන් කොපමණ ඇස් ප්‍රමාණයක පළලට සමාන වේද?", "ඇස් පහක පළලට (5 eye widths)", "ඇස් දෙකක පළලට (2 eye widths)", "ඇස් දහයක පළලට (10 eye widths)", "එක් ඇසක පළලට (1 eye width)", "වම් කන-ඇස-මැද පරතරය-ඇස-දකුණු කන ලෙස තිරස්ව ඇස් පහක පළලට මුහුණ බෙදිය හැකිය."),
        q("සිටගෙන සිටින සාමාන්‍ය වැඩිහිටි මිනිසෙකුගේ 'දණහිස් සන්ධිය' පොළොවේ සිට මැනීමේදී පිහිටන්නේ මුළු උසෙන් කොපමණ ප්‍රමාණයකද?", "හතරෙන් එකක් (හිස් 2ක්) පමණ ඉහළින්", "හරි අඩක් (හිස් 4ක්) පමණ ඉහළින්", "හතරෙන් තුනක් (හිස් 6ක්) පමණ ඉහළින්", "පතුලට සමානව හිස අසලින්", "පාදයේ පතුලේ සිට උකුළ දක්වා ඇති දුරෙන් හරි අඩක මට්ටමේ දණහිස පිහිටයි."),
        q("සිටගෙන සිටින වැඩිහිටි පුද්ගලයෙකුගේ දෙඅත් පහළට හෙළා සිටින විට ඔහුගේ 'ඇඟිලි තුඩු' පිහිටන්නේ කුමන ශරීර මට්ටමේද?", "කලවා මැද ප්‍රදේශයේ", "දණහිසට පහළින් බටකොළ අසල", "පපුව මැද ඉළ ඇට අසල", "උකුළ ඇටයට බොහෝ ඉහළින්", "මැණික් කටුව උකුළ අසල පිහිටන අතර ඇඟිලි තුඩු කලවා මැද දක්වා විහිදේ."),
        q("සම්මත වැඩිහිටි මානව මුහුණේ උසට (නිකට සිට නළල හිසකෙස් සීමාව දක්වා) සමාන වන ශරීර අවයවය කුමක්ද?", "මැණික් කටුවේ සිට මැදැඟිල්ල දක්වා අත", "උරහිසේ සිට පාදයේ ඇඟිලි දක්වා දිග", "කලවයේ සිට දණහිස දක්වා දුර", "බෙල්ලේ හරස්කඩ වටප්‍රමාණය", "මිනිස් අතක් මුහුණ මත තැබූ විට එය නිකට සිට නළල ඉහළ දක්වා ප්‍රමාණයට ආසන්නව සමාන වේ."),
        q("වැඩිහිටියෙකුගේ පාදයේ පතුලේ සම්පූර්ණ දිග බොහෝ විට සමාන වන්නේ සිරුරේ කුමන කොටසේ දිගටද?", "වැලමිටේ සිට මැණික් කටුව දක්වා බාහුවට", "නාසයේ සිට නිකට දක්වා කුඩා දුරට", "හිසේ මුදුනේ සිට පතුල දක්වා උසට", "එක් කනක උපරිම උසට", "මෙම සරල ව්‍යුහ විද්‍යාත්මක සමානුපාතය චරිත ඇඳීමේදී පාද කුඩා හෝ විශාල වීම වළක්වයි."),
        q("මිනිසෙකු එක් පාදයකට බර දී සිටගන්නා (Contrapposto) විට ඔහුගේ උරහිස් රේඛාව සහ උකුළු රේඛාව පිහිටන්නේ කෙසේද?", "එකිනෙකට ප්‍රතිවිරුද්ධ කෝණවලට ඇලවී", "සම්පූර්ණයෙන්ම තිරස්ව හා සමාන්තරව", "සිරස් අතට කෙළින් එක පෙළට", "මැදින් කැඩී වෙන් වූ ලෙස", "බර දරන පැත්තේ උකුළ ඉහළට එසවෙන විට සමබරතාව රැකීමට එම පැත්තේ උරහිස මඳක් පහත් වේ."),
        q("චලනය වන මානව රූපයක් ක්ෂණිකව ඇඳීම ආරම්භ කිරීමේදී මුලින්ම අඳිනු ලබන සිරුරේ රිද්මය දක්වන මූලික රේඛාව කුමක්ද?", "ක්‍රියා රේඛාව (Line of Action)", "ක්ෂිතිජ රේඛාව (Horizon Line)", "අතුරුදන් රේඛාව (Vanishing Line)", "වට රාමු රේඛාව (Border Line)", "කොඳු ඇට පෙළ හා පාද දිගේ යන තනි ගලා යන ක්‍රියා රේඛාවක් සිරුරට ජීවමාන චලනයක් දෙයි."),
        q("පැන්සල් හෝ අඟුරු සිතුවමක සියුම් ආලෝක තිත් මැකීමට හා මතුපිට තද රබර් කුඩු නොමැතිව මෘදු කිරීමට ගන්නා මකනය කුමක්ද?", "අඹරන මෘදු මකනය (Kneaded Eraser)", "තද වැලි කඩදාසි මකනය (Sand Eraser)", "තෙත් රෙදි කැබැල්ල (Wet Rag)", "වීදුරු පිහි තලය (Razor Blade)", "මැටි මෙන් අතේ හැඩයට අඹරා ගත හැකි මෙම මකනය චිත්‍ර කඩදාසියේ තන්තු ඉරී යාමකින් තොරව පැන්සල් තානය අඩු කරයි."),
        q("පැන්සල් හෝ චාකෝල් සෙවණැලි ඇඟිල්ලෙන් අතුල්ලනවා වෙනුවට සුමටව මුසු කිරීමට භාවිත කරන රෝල් කළ කඩදාසි උපකරණය කුමක්ද?", "බ්ලෙන්ඩින් ස්ටම්ප් / ටෝටිලියොන්", "පැලට් පිහිය (Palette Knife)", "ටියැන්ටින් නළය (Tjanting Tool)", "රෝලර් බ්‍රේයර් (Brayer Roller)", "ඇඟිලිවල ඇති ස්වාභාවික තෙල් කඩදාසියේ තැවරීම වළක්වා පිරිසිදු තාන සංක්‍රාන්ති සෑදීමට මෙය උපකාරී වේ."),
        q("ගල් අඟුරු (Charcoal) හෝ හුණු පැස්ටල් සිතුවමක් ඇඳ අවසන් වූ පසු කුඩු හැලී බොඳ වීම වැළැක්වීමට ඉසින ද්‍රාවණය කුමක්ද?", "ස්ථායීකාරක ඉසිනය (Fixative Spray)", "ටර්පන්ටයින් තෙල් (Turpentine)", "දියර ජල සායම් (Watercolor)", "රබර් කිරි ද්‍රාවණය (Latex)", "විනිවිද පෙනෙන ආරක්ෂිත පටලයක් ලෙස ඉසින ස්ථායීකාරකය කුඩු කඩදාසියට තදින් සවි කරයි."),
        q("රේඛා සැකිල්ලක් ඇඳීමට අධික කළු නොවන මෙන්ම කඩදාසිය හාරන්නේද නැති සාමාන්‍ය මධ්‍යම පැන්සල් ශ්‍රේණිය කුමක්ද?", "HB පැන්සල", "9H පැන්සල", "8B පැන්සල", "6B පැන්සල", "මූලික සටහන් (Layout sketch) ඇඳීමේදී පහසුවෙන් මැකිය හැකි මධ්‍යම තද බවක් ඇති HB පැන්සල වඩාත් සුදුසුය."),
        q("දිය සායම් කඩදාසි මතුපිට ස්වභාවය අනුව ඉතා සිනිඳු විස්තර ඇඳීමට 'Hot Press' කඩදාසියද සාමාන්‍ය වැඩ සඳහා ගන්නේ කුමන කඩදාසියද?", "Cold Press (මධ්‍යම රළු) කඩදාසිය", "වැලි කඩදාසි (Sandpaper)", "සිනිඳු පොලිතින් පත්‍ර (Polythene)", "තුනී ටිෂූ කඩදාසිය (Tissue Paper)", "කෝල්ඩ් ප්‍රෙස් කඩදාසිය ජලය හොඳින් උරා ගන්නා අතර සුමට සේදුම් හා රේඛා දෙකටම ගැළපේ."),
        q("තුනී දිය සායම් කඩදාසියක් තෙත් වූ විට රැලි ගැසීම වැළැක්වීම සඳහා ඇඳීමට පෙර ගන්නා පූර්ව පියවර කුමක්ද?", "කඩදාසිය තෙත් කර ගම් පටියකින් ලෑල්ලේ ඇද බැඳ තැබීම", "කඩදාසිය ඉටිපන්දමකින් පුලුස්සා වියළීම", "කඩදාසිය මත ඝන තෙල් ආලේප කිරීම", "කඩදාසිය හතරට නමා මිටියකින් තැළීම", "තෙත් කඩදාසිය වියළෙන විට ඇදී පැතලි වන සේ ඇලවීමෙන් පසුව තීන්ත ගෑවද රැලි නොගැසේ."),
        q("දිය සායම් සිතුවමක වැරදීමකින් තද වූ තැනක් හෝ වලාකුළක සුදු පැහැයක් තෙත්ව තිබියදී මතු කර ගැනීමේ ශිල්පය කුමක්ද?", "පිරිසිදු ටිෂූ හෝ තෙත් පින්සලෙන් වර්ණ ඉසිලීම (Lifting)", "මතට ඝන කළු තෙල් තීන්ත ආලේප කිරීම", "කතුරෙන් කඩදාසිය සිදුරු කර කැපීම", "ලුණු කුඩු අහුරක් තදින් ඇතිල්ලීම", "පැල්ලම් නොගැසෙන වර්ණක පිරිසිදු තෙත් පින්සලකින් හෝ කඩදාසි තුවායකින් මෘදුව උරා ඉවත් කළ හැකිය."),
        q("අර්ධ වශයෙන් වියළෙමින් පවතින දිය සායම් තලයක් මත පිරිසිදු ජල බිඳුවක් වැටුණු විට දාරයේ ඇතිවන මල් පෙති වැනි සලකුණ කුමක්ද?", "බ්ලූම් හෙවත් බැක්රන් (Watercolor Bloom)", "ඉම්පැස්ටෝ ස්තරය (Impasto Layer)", "ස්ග්‍රැෆිටෝ රේඛාව (Sgraffito Line)", "ලිතොග්‍රැෆි මුද්‍රාව (Litho Print)", "ජලය විසින් අවට තීන්ත තල්ලු කිරීමෙන් මෙය සිදුවන අතර නිර්මාණශීලී වයන සෑදීමටද එය යොදා ගැනේ."),
        q("තෙල් සායම් හෝ ඇක්‍රිලික් චිත්‍ර ඇඳීමේදී තීන්ත පැලට්ටුව මත මිශ්‍ර කිරීමට හා ඝනව තැවරීමට භාවිත කරන නම්‍යශීලී ලෝහ උපකරණය කුමක්ද?", "පැලට් පිහිය (Palette Knife)", "ගල් කටුව (Stone Chisel)", "වැලි පනාව (Wire Comb)", "කැපුම් කතුර (Craft Scissors)", "පැලට් පිහියෙන් මිශ්‍ර කිරීම නිසා පින්සල් කෙඳි ගෙවී යාම වැළකෙන අතර විචිත්‍ර වයන නිර්මාණය කළ හැකිය."),
        q("තෙල් සායම් මාධ්‍යයේදී ටර්පන්ටයින් (Turpentine) වියළීම ඉක්මන් කර පැහැය අඩු කරන අතර හණ තෙල් (Linseed Oil) කිරීමට සමත් වන්නේ කුමක්ද?", "දිලිසෙන බව වැඩි කර වියළීම ප්‍රමාද කිරීම", "තීන්ත ජලයේ සම්පූර්ණයෙන් දිය කර හැරීම", "චිත්‍රය කළු සුදු පැහැයට හැරවීම", "කැන්වසය ප්ලාස්ටික් බවට පත් කිරීම", "හණ තෙල් වැඩි කරමින් උඩ ස්තර ඇඳීම 'Fat-over-lean' නීතියට අනුකූල වීමටද උපකාරී වේ."),
        q("උණුසුම් පරිසරයේදී ඉතා ඉක්මනින් වියළෙන ඇක්‍රිලික් තීන්ත වැඩි වේලාවක් තෙත්ව තබා මිශ්‍ර කිරීමට එකතු කරන ද්‍රව්‍යය කුමක්ද?", "ඇක්‍රිලික් රිටාඩර් (Acrylic Retarder)", "භූමිතෙල් (Kerosene)", "සිමෙන්ති කුඩු (Cement)", "ලුණු ද්‍රාවණය (Brine)", "ප්‍රමාදකාරක මාධ්‍යයක් එක් කිරීමෙන් තෙල් සායම් මෙන් සුමට වර්ණ මිශ්‍රණයක් ඇක්‍රිලික්වලින් ලබාගත හැකිය."),
        q("යුරෝපීය පුනරුදයට පෙර සම්භාව්‍ය 'එග් ටෙම්පරා' (Egg Tempera) සිතුවම් සෑදීමේදී වර්ණ කුඩු සමඟ මිශ්‍ර කළ බන්ධකය කුමක්ද?", "බිත්තර කහමදය (Egg Yolk)", "මී පැණි (Honey)", "පෙට්‍රල් (Petrol)", "කැල්සියම් කාබයිඩ්", "ජලය හා බිත්තර කහමදය එක්කළ ටෙම්පරා තීන්ත ඉක්මනින් වියළී සියවස් ගණනාවක් දීප්තිමත්ව පවතී."),
        q("පෝස්ටර් වර්ණ හෙවත් ගුවාෂ් (Gouache) සහ ඇක්‍රිලික් තීන්ත වියළුණු පසු ජලය ගෑ විට දක්වන ප්‍රධාන වෙනස කුමක්ද?", "ගුවාෂ් නැවත දිය වන අතර ඇක්‍රිලික් ජල ප්‍රතිරෝධී වේ", "ඇක්‍රිලික් දිය වන අතර ගුවාෂ් ගල් මෙන් තද වේ", "දෙවර්ගයම කිසි විටෙක වියළෙන්නේ නැත", "දෙවර්ගයම තෙල්වලින් පමණක් සෝදා හැරිය යුතුය", "ඇක්‍රිලික් වියළුණු විට ප්ලාස්ටික් පටලයක් මෙන් ජලයට ඔරොත්තු දෙන බැවින් ස්තර ගණනාවක් මත ඇඳිය හැකිය."),
        q("චීන හා ජපන් පින්සල් කලාවේ මෙන් තද කළු තීන්ත ජලය සමඟ විවිධ අනුපාතවලින් තුනී කර තාන මැවීමේ ක්‍රමය කුමක්ද?", "ඉන්ක් වොෂ් (Ink Wash / Sumi-e)", "ඉම්පැස්ටෝ (Impasto)", "එන්කෝස්ටික් (Encaustic)", "ලිනෝ කට් (Linocut)", "තනි කළු තීන්තයේ සාන්ද්‍රණය වෙනස් කරමින් මෘදු මීදුමේ සිට තද ගල් පර්වත දක්වා දැක්විය හැකිය."),
        q("මැපින් පෑන් තුඩක් හෝ ඩිප් පෑනක් (Dip Pen) යොදා දියර තීන්තෙන් සිතුවම් කිරීමේදී තාන අඳුර ගොඩනගන්නේ කෙසේද?", "හැචිං, ක්‍රොස්-හැචිං හා ස්ටිප්ලින් මගින්", "ඇඟිල්ලෙන් තෙත් තීන්ත අතුල්ලමින්", "පෑනෙන් කඩදාසිය ඉරා දමමින්", "සුදු පැස්ටල් කූරු මිශ්‍ර කරමින්", "තීන්ත වර්ණයක් නොමැතිව රේඛාවල ඝනත්වය හා පරතරය වෙනස් කිරීමෙන් පැහැදිලි සෙවණැලි මැවේ."),
        q("පාට පැන්සල් (Colored Pencils) චිත්‍රයක මතුපිට කඩදාසියේ සුදු තිත් නොපෙනෙන සේ තදින් ස්තර ගණනක් ගා ඔප දැමීමේ ශිල්පය කුමක්ද?", "බර්නිෂින් ක්‍රමය (Burnishing)", "ෆ්‍රොටාජ් ක්‍රමය (Frottage)", "සේදුම් ක්‍රමය (Washing)", "බිස්ක් පිළිස්සීම (Bisque)", "සුදු හෝ ලා පැහැ පාට පැන්සලකින් තදින් උඩින් ගෑමෙන් වර්ණ තීන්ත මෙන් සුමටව මිශ්‍ර වේ."),
        q("තෙල් සායම් සිතුවමක් ආරම්භයේදී සම්පූර්ණ වර්ණ ගැන්වීමට පෙර තුනී තනි පැහැයකින් (උදා: Burnt Umber) අඳින මූලික ස්තරය කුමක්ද?", "යටි සිතුවම (Underpainting)", "අවසන් වාර්නිෂ් ස්තරය (Varnish)", "පතිත සෙවණැල්ල (Cast Shadow)", "රාමු මායිම (Mount Border)", "ආලෝක-අඳුරු තාන සැලැස්ම කල්තියා ස්ථාපිත කර ගැනීමට යටි සිතුවම ඉතා වැදගත් වේ."),
        q("කුඩා ඡායාරූපයක් හෝ සටහනක් අනුපාත වරදවා නොගෙන විශාල කැන්වසයක් මත පිටපත් කිරීමේ සරල ජ්‍යාමිතික ක්‍රමය කුමක්ද?", "කොටු දැල් ක්‍රමය (Grid Method)", "තෙත මත තෙත ක්‍රමය (Wet-on-Wet)", "වියළි පින්සල් ක්‍රමය (Dry Brush)", "තිත් මුද්‍රණ ක්‍රමය (Stippling)", "මුල් රූපයේ හා විශාල කඩදාසියේ සමාන කොටු ගණනක් ඇඳ කොටුවෙන් කොටුවට රේඛා පිටපත් කෙරේ."),
        q("සම්පූර්ණ කළ පැන්සල් සටහනක් එහි පිටුපස මෘදු පැන්සලකින් අඳුරු කර හොඳ චිත්‍ර කඩදාසියක් මත පිටපත් කිරීම හඳුන්වන්නේ කෙසේද?", "ග්‍රැෆයිට් හුවමාරු ක්‍රමය (Graphite Transfer)", "බතික් ඉටි ක්‍රමය (Wax Batik)", "සකපෝරු ක්‍රමය (Wheel Throwing)", "මොසැයික් ක්‍රමය (Mosaic)", "පිරිසිදු දිය සායම් කඩදාසියේ මකන පහරවල් ඉතිරි නොකර සටහන මාරු කිරීමට මෙය ඉතා ප්‍රයෝජනවත්ය."),
        q("නිශ්චල ජීව චිත්‍රයක පසුබිමේ එල්ලා ඇති 'රෙදි කඩක රැළි' (Drapery folds) යථාර්ථවාදීව ඇඳීමේදී ඒවා සැලකිය යුත්තේ කුමන ආකෘති ලෙසද?", "නැමුණු සිලින්ඩර හා කේතු ආකෘති ලෙස", "පැතලි සෘජුකෝණාස්‍ර කොටු ලෙස", "විසිරුණු අහඹු තිත් රටා ලෙස", "තියුණු හතරැස් පෙට්ටි ලෙස", "සෑම රෙදි රැල්ලකටම සිලින්ඩරයක මෙන් ආලෝකය, හර සෙවණැල්ල හා පරාවර්තන ආලෝකය ඇත."),
        q("විනිවිද පෙනෙන වීදුරු බෝතලයක් මේස රෙද්දක් ඉදිරිපිට තබා අඳින විට බෝතලය තුළින් පෙනෙන පසුබිම් රේඛාව දිස්වන්නේ කෙසේද?", "වර්තනය නිසා කැඩී හා නැමී", "සම්පූර්ණයෙන්ම කෙළින් හා නොවෙනස්ව", "කළු පැහැති ඝන කුට්ටියක් ලෙස", "රන්වන් ඉරි පෙළක් ලෙස", "වීදුරුවේ ඝනකම හා වක්‍රතාව අනුව ආලෝකය නැමෙන (Refraction) ආකාරය නිරීක්ෂණය කිරීම සජීවී බව වැඩි කරයි."),
        q("ස්වභාවධර්ම අධ්‍යයන (Nature Drawing) චිත්‍රයක ශාක පත්‍රයක් හෝ මලක් ඇඳීමේදී මුලින්ම අවධානය දිය යුත්තේ කුමකටද?", "ප්‍රධාන කඳ, නහර රටාව හා සමස්ත හැඩයේ සමානුපාතයට", "තනි කුඩා සිදුරකට පමණක් පාට කිරීමට", "පසුබිම් වර්ණය තද කළු කිරීමට", "කෝදුවකින් මල් පෙති සෘජු කොටු කිරීමට", "පොදු හැඩය හා නහර දිශාව නිවැරදිව සැකසූ පසු සියුම් වයන හා තාන එක් කිරීම සුදුසුය."),
        q("චිත්‍රාගාරයෙන් පිටතට ගොස් ස්වාභාවික පරිසරය සජීවීව සිතුවම් කිරීමේ කලා සම්ප්‍රදාය හඳුන්වන ප්‍රංශ යෙදුම කුමක්ද?", "ඔන් ප්ලේන් එයාර් (En Plein Air)", "ට්‍රොම්ප් ලොයිල් (Trompe l'oeil)", "චියාරොස්කියුරෝ (Chiaroscuro)", "සෝක් ස්ටේන් (Soak-stain)", "ඉර එළිය ඉක්මනින් වෙනස් වන බැවින් එළිමහන් සිතුවම්කරණයේදී වේගවත් සංයුති හා ආලෝක ග්‍රහණය වැදගත් වේ."),
        q("අ.පො.ස. (සා.පෙළ) චිත්‍ර විභාගයේ 'චිත්‍ර රචනය' (Composition) ප්‍රශ්නයේදී මිනිස් රූප කිහිපයක් පෙළ ගැස්වීමේ හොඳම ක්‍රමය කුමක්ද?", "ක්‍රියාශීලී ඉරියව්, ප්‍රමාණ වෙනස හා වැසී යාම යෙදීම", "සියලු රූප එකම උසින් සෘජු පේළියක තැබීම", "පසුබිම සම්පූර්ණයෙන්ම හිස් සුදුවට තැබීම", "රූප සියල්ල කුඩා මුද්දර මෙන් කොනකට කිරීම", "පෙරබිමේ විශාල රූප හා පසුබිමේ කුඩා රූප එක්කිරීමෙන් ගැඹුර හා නාට්‍යමය ජීවය ගොඩනැගේ."),
        q("අ.පො.ස. (සා.පෙළ) 'මෝස්තර නිර්මාණ' ප්‍රායෝගික අංශයේදී ඉහළ ලකුණු ලබා ගැනීමට වඩාත් වැදගත් වන තාක්ෂණික ගුණාංගය කුමක්ද?", "පිරිසිදු දාර, සම වර්ණ තැවරීම හා නිවැරදි සමබරතාව", "තීන්ත දාරවලින් පිටතට විසිරී තිබීම", "පැන්සල් මැකුම් කුණු කඩදාසියේ රැඳී තිබීම", "වර්ණ මිශ්‍ර නොකර අපිරිසිදුව ගෑම", "නිර්මාණාත්මක අදහස මෙන්ම පිරිසිදු නිමාව (Neatness) මෝස්තර නිර්මාණ ඇගයීමේදී තීරණාත්මක වේ."),
        q("දිය සායම් පැලට්ටුවක වියළී ඉතිරි වූ තීන්ත නැවත භාවිත කළ හැකි වුවද, තෙල් සායම් භාවිතයෙන් පසු කළ යුත්තේ කුමක්ද?", "පැලට්ටුව පිරිසිදු කර පින්සල් ටර්පන්ටයින්වලින් සේදීම", "තෙල් සායම් පින්සල් වතුරේ පොඟවා තැබීම", "වියළි තෙල් පැලට්ටුවේ තීන්ත අව්වේ වේලීම", "පින්සල් සියල්ල වැලිවලින් ඇතිල්ලීම", "තෙල් සායම් කෙඳි මත වියළුණහොත් පින්සල සදහටම ගල් වන බැවින් වහාම පිරිසිදු කළ යුතුය."),
        q("වර්ණ චක්‍රය හා තාන පරිමාණය අධ්‍යයනය කිරීමෙන් පසු එළිමහන් භූ දර්ශනයක් සිතුවම් කිරීමේදී අහස හා පොළොව වෙන්වන රේඛාව තැබිය යුතු සුදුසුම තැන කොතැනද?", "හරි මැදින් නොතබා ඉහළ හෝ පහළ තුනෙන් එක අසල", "සැමවිටම කඩදාසියේ හරි මැදින් සමව බෙදෙන සේ", "කඩදාසියේ ඉහළම දාරයේ කෙළින්ම", "විකර්ණ අතට කොනක සිට කොනකට ඇද", "ක්ෂිතිජ රේඛාව හරි මැදින් තැබූ විට සිතුවම සම කොටස් දෙකකට බෙදී සංයුතිය දුර්වල විය හැකිය."),
        q("චිත්‍ර පන්තියේදී 'නිශ්චල ජීව' සංයුතියක් අඳින විට වස්තූන් වෙත වැටෙන ආලෝක ප්‍රභව කීයක් තිබීම වඩාත් සුදුසුද?", "තනි ප්‍රධාන ආලෝක ප්‍රභවයක්", "සෑම දිශාවකින්ම දැල්වූ විදුලි බුබුළු දහයක්", "කිසිදු ආලෝකයක් නොමැති අඳුරු කාමරයක්", "නිතර එහා මෙහා ගෙන යන විදුලි පන්දමක්", "තනි පැහැදිලි ආලෝක ප්‍රභවයක් තිබීමෙන් පැහැදිලි එළිය, හර සෙවණැල්ල හා පතිත සෙවණැල්ල අධ්‍යයනය පහසු වේ."),
        q("ජල සායම් පින්සලක් තීන්ත සමඟ භාවිත කර අවසන් වූ පසු ගබඩා කර තැබිය යුතු නිවැරදි ආකාරය කුමක්ද?", "සෝදා තිරස්ව හෝ කෙඳි උඩට සිටින සේ තැබීම", "තෙත පින්සල කෙඳි යටට සිටින සේ වතුර කෝප්පයේ තැබීම", "තීන්ත පිටින්ම වියළී යාමට පොතක් ඇතුළේ තැබීම", "උණු වතුරේ පැය ගණනක් තම්බා තැබීම", "කෙඳි යටට හරවා වතුරේ තැබීමෙන් පින්සල් තුඩ ඇද වන අතර ලී මිට ඉදිමී පුපුරා යයි."),
        q("ප්‍රායෝගික චිත්‍ර ඇඳීමේදී ඇඳි රූපයක් නිවැරදිදැයි ක්ෂණිකව හඳුනා ගැනීමට කලාකරුවන් කඩදාසිය කණ්ණාඩියකින් බලන්නේ ඇයි?", "ඇස හුරු වූ සමානුපාත දෝෂ ආපසු හැරවූ විට පැහැදිලිව පෙනෙන නිසා", "කඩදාසියේ වර්ණ දීප්තිමත් වැඩි නිසා", "පැන්සල් රේඛා කණ්ණාඩියෙන් මැකී යන නිසා", "වස්තුවේ ප්‍රමාණය දෙගුණ කර බැලීමට", "දිගු වේලාවක් එකම චිත්‍රය දෙස බැලීමෙන් මගහැරෙන ඇලවීම් හා අසමතුලිතතා කැඩපත් ප්‍රතිබිම්බයෙන් වහාම හසු වේ.")
    )
}
